('gleif-global-lei', 'GLEIF Global LEI Index / Golden Copy', 'Global Legal Entity Identifier Foundation', 'https://www.gleif.org/en/lei-data/access-and-use-lei-data', 'CC0-1.0', 'approved', 1, 1, 0, NULL, 'free_bulk_and_api', 'up_to_three_times_daily_for_golden_copy_and_deltas', '["global"]', '["legal_entity_name","registered_address","entity_status","legal_form","registration_authority","parent_relationships_where_reported"]', '["LEI population only; not a complete register of every small business or logistics carrier","preserve source record status and timestamps","do not imply GLEIF endorsement","access LEIs and reference data only through the official GLEIF Access Service; do not bypass technical restrictions","do not claim proprietary rights in LEIs or imply GLEIF/LOU support or a special relationship","GLEIF disclaims accuracy and availability; retain record validation/status and retrieval time"]', '["https://www.gleif.org/en/about/open-data/","https://www.gleif.org/en/meta/lei-data-terms-of-use"]', 'candidate', 'not_required', NULL, '2026-11-07'),
('wikidata-structured-data', 'Wikidata structured data', 'Wikimedia Foundation / Wikidata contributors', 'https://www.wikidata.org/wiki/Wikidata:Licensing', 'CC0-1.0', 'approved', 1, 1, 0, NULL, 'public_dumps_and_query_services', 'unknown', '["global"]', '["organization_entities","aliases","official_websites_where_present","country","industry_and_relationship_claims_where_present"]', '["community-maintained; completeness and freshness vary","retain item IDs and statement references","do not treat every claim as authoritative or current"]', '["https://www.wikidata.org/wiki/Wikidata:Copyright","https://www.wikidata.org/wiki/Wikidata:Licensing"]', 'candidate', 'not_required', NULL, '2026-11-07'),
('finland-prh-ytj', 'Finnish Business Information System / PRH Open Data', 'Finnish Patent and Registration Office', 'https://avoindata.prh.fi/en', 'CC-BY-4.0', 'approved', 1, 1, 1, 'Source: Finnish Patent and Registration Office (PRH), Finnish Business Information System open data.', 'free_api_and_bulk_file', 'daily', '["FI"]', '["registered_company_names","business_ids","company_forms","registered_addresses","tax_register_membership"]', '["private traders are excluded","email addresses and phone numbers are not supplied","do not use PRH/Finnish Business Information System logos or mimic official service design"]', '["https://avoindata.prh.fi/en/info/swagger-ui","https://avoindata.suomi.fi/data/en_GB/dataset/prh-avoin-data"]', 'candidate', 'not_required', NULL, '2026-11-07'),
('latvia-enterprise-register', 'Latvian Enterprise Register Open Data', 'Register of Enterprises of the Republic of Latvia', 'https://data.gov.lv/dati/eng/dataset/uz', 'CC0-1.0', 'approved', 1, 1, 0, NULL, 'free_daily_CSV_and_portal_API', 'daily', '["LV"]', '["legal_entity_type","registered_address","current_legal_name","registration_number","EU_payment_recipient_identifier_where_assigned","registration_date","deregistration_or_reorganisation_date"]', '["official portal marks the base Enterprise Register dataset CC0-1.0 and a high-value dataset for companies and company ownership","the source includes all registered subjects; filter and separately review natural-person and sole-proprietor records before public display","do not assume the separate shareholder, sanctions, or annual-report datasets share the same field-level privacy profile even where they are also CC0"]', '["https://data.gov.lv/dati/eng/dataset/uz","https://www.ur.gov.lv/en/registers-open-data-latvian-open-data-portal"]', 'candidate', 'pending', NULL, '2026-11-07'),
('us-sec-edgar', 'US SEC EDGAR company submissions and XBRL APIs', 'United States Securities and Exchange Commission', 'https://data.sec.gov/', 'US_GOVERNMENT_CONTENT_REUSE_POLICY', 'approved', 1, 1, 1, 'Source: US SEC EDGAR company submissions and XBRL APIs. Follow the publisher''s attribution and licence conditions in the linked evidence.', 'free_unauthenticated_json_api', 'throughout_day', '["US","issuers_reporting_to_SEC"]', '["SEC_filers","company_submissions","filing_metadata","XBRL_company_facts"]', '["not a complete US business registry","automated clients must follow SEC fair-access and privacy/security policies","third-party exhibits or embedded copyrighted materials may have separate rights"]', '["https://www.sec.gov/about/webmaster-frequently-asked-questions","https://www.sec.gov/about/developer-resources","https://www.sec.gov/search-filings/edgar-search-assistance/accessing-edgar-data"]', 'candidate', 'pending', NULL, '2026-11-07'),
('govdatahub-open-data-index', 'GovDataHub Open Data Index', 'GovDataHub contributors', 'https://github.com/GovDataHub/open-data-index', 'public_domain|CC0-1.0|CC-BY|OGL-3.0|OGL-Canada', 'approved', 1, 1, 1, 'Source: GovDataHub Open Data Index. Follow the publisher''s attribution and licence conditions in the linked evidence.', 'GitHub_CSV_and_JSON', 'unknown', '["multi_country"]', '["dataset_metadata","publisher","landing_page","license_evidence"]', '["index metadata is not the underlying dataset","each selected dataset must be checked at publisher source","quarantined/unverified entries must remain excluded"]', '["https://github.com/GovDataHub/open-data-index"]', 'discovery', 'not_required', NULL, '2026-11-07'),
('datenoio-data-portals-registry', 'Dateno Data Portals Registry', 'datenoio', 'https://github.com/datenoio/dataportals-registry', 'CC-BY-4.0', 'approved', 1, 1, 1, 'Source: Dateno Data Portals Registry. Follow the publisher''s attribution and licence conditions in the linked evidence.', 'JSONL_PARQUET_DUCKDB', 'unknown', '["global"]', '["data_portal_catalog_metadata","catalog_publisher","country","catalog_platform"]', '["describes data portals/catalogues, not the datasets themselves","follow each portal to the original publisher and verify each dataset license"]', '["https://github.com/datenoio/dataportals-registry"]', 'discovery', 'not_required', NULL, '2026-11-07'),
('opencorporates-commercial-api', 'OpenCorporates website and API', 'OpenCorporates Ltd', 'https://opencorporates.com/terms-of-use/', 'ODbL-1.0_DATABASE_PLUS_SEPARATE_API_TERMS', 'blocked', 0, 0, 1, 'Source: OpenCorporates website and API. Follow the publisher''s attribution and licence conditions in the linked evidence.', 'website_personal_use_only_without_subscription; API_key_and_contract', 'unknown', '["global"]', '["company_registry_data"]', '["website free access is personal use only","API internal-use license bars third-party access and public third-party services","external distribution license is limited to qualifying derivative works and must be selected/contracted","ODbL database share-alike obligations apply"]', '["https://opencorporates.com/terms-of-use/","https://opencorporates.com/legal-information/self-service-api-terms-of-service/"]', 'blocked', 'pending', NULL, '2026-11-07'),
('openstreetmap-business-pois', 'OpenStreetMap points of interest', 'OpenStreetMap contributors', 'https://www.openstreetmap.org/copyright', 'ODbL-1.0', 'approved', 1, 1, 1, 'Source: OpenStreetMap points of interest. Follow the publisher''s attribution and licence conditions in the linked evidence.', 'bulk_extracts_and_overpass', 'unknown', '["global"]', '["business_pois","addresses","locations","category_tags"]', '["derived public databases must comply with ODbL share-alike","keep as a separate licensed dataset or publish the resulting database under compatible terms","public tile service has separate usage policy"]', '["https://www.openstreetmap.org/copyright","https://osmfoundation.org/wiki/Licence/Licence_and_Legal_FAQ"]', 'candidate', 'not_required', NULL, '2026-11-07'),
('ireland-cro-company-records', 'Ireland Companies Registration Office — Company Records', 'Companies Registration Office (Ireland)', 'https://opendata.cro.ie/dataset/companies', 'CC-BY-4.0', 'approved', 1, 1, 1, 'Source: Ireland Companies Registration Office — Company Records. Follow the publisher''s attribution and licence conditions in the linked evidence.', 'free_bulk_csv_and_api', 'daily', '["IE"]', '["current_company_records","historical_dissolved_or_closed_records","company_identifiers","registered_company_details"]', '["dataset metadata and publisher source must be retained","do not infer company status beyond the source snapshot timestamp","review any personal data fields separately"]', '["https://data.europa.eu/data/datasets/bf6f837d-0946-4c14-9a99-82cd6980c121"]', 'candidate', 'pending', NULL, '2026-11-07'),
('uk-companies-house-register', 'UK Companies House Free Company Data Product and public register', 'Companies House', 'https://www.gov.uk/guidance/companies-house-data-products', 'STATUTORY_PUBLIC_REGISTER_REUSE_NOT_OGL', 'approved', 1, 1, 1, 'Source: UK Companies House Free Company Data Product and public register. Follow the publisher''s attribution and licence conditions in the linked evidence.', 'free_monthly_bulk_csv_and_free_public_register_uri; API_requires_account_and_credentials', 'monthly_bulk_snapshot; live_API', '["GB"]', '["live_company_names","company_type","registered_office_address","SIC","company_status","filing_dates","previous_names"]', '["Companies House states it imposes no rules or requirements on use of public-register information, but users remain responsible for data-protection, copyright and other applicable law","do not mislabel the public-register data as OGL-licensed","bulk product is a monthly snapshot; retain snapshot date"]', '["https://www.gov.uk/guidance/companies-house-data-products","https://developer.company-information.service.gov.uk/"]', 'candidate', 'not_required', NULL, '2026-11-07'),
('world-company-database-github-index', 'World Company Database — official registry and open dataset index', 'Alessandro114 / S.C.A.L.A. Score maintainers', 'https://github.com/Alessandro114/world-company-database', 'CC-BY-4.0', 'approved', 1, 1, 1, 'Source: World Company Database by Alessandro114, CC BY 4.0; individual underlying datasets retain their own publisher licences.', 'GitHub_markdown_and_linked_publisher_sources', 'unknown', '["global"]', '["official_registry_directory","country_coverage_metadata","dataset_license_claims_and_source_links"]', '["repository license applies to the index content only, not the underlying registry data","maintainer says dataset licences were checked on publisher pages as of 2026-10-02; re-check each source at its official publisher before ingestion","free browser lookup does not imply free bulk/API redistribution"]', '["https://github.com/Alessandro114/world-company-database"]', 'discovery', 'not_required', NULL, '2026-11-07'),
('norway-brreg-enhetsregisteret', 'Norway Brønnøysund Central Coordinating Register for Legal Entities', 'Brønnøysund Register Centre', 'https://www.brreg.no/en/use-of-data-from-the-bronnoysund-register-centre/open-data/', 'NLOD-2.0', 'approved', 1, 1, 1, 'Source: Brønnøysund Register Centre, Open Data from the Central Coordinating Register for Legal Entities, NLOD 2.0.', 'free_API_bulk_JSON_CSV_XLSX_and_updates', 'bulk_files_daily; APIs_real_time_and_updates', '["NO"]', '["legal_entity_names","organisation_numbers","organisation_forms","addresses","industrial_codes","sub_entities","public_group_structure"]', '["do not access authorised endpoints containing national identity numbers or other restricted personal data","preserve source record and update timestamps","follow NLOD 2.0 attribution and notice requirements"]', '["https://www.brreg.no/en/use-of-data-from-the-bronnoysund-register-centre/open-data/","https://data.brreg.no/enhetsregisteret/api/dokumentasjon/en/index.html","https://www.brreg.no/en/use-of-data-from-the-bronnoysund-register-centre/datasets-and-api/data-about-organisations/"]', 'candidate', 'pending', NULL, '2026-11-07'),
('france-insee-sirene', 'France INSEE SIRENE register', 'Institut national de la statistique et des études économiques (INSEE)', 'https://www.insee.fr/fr/information/3591226', 'LICENCE-OUVERTE-2.0', 'approved', 1, 1, 1, 'Source: France INSEE SIRENE register. Follow the publisher''s attribution and licence conditions in the linked evidence.', 'free_daily_API_and_full_bulk_files_including_Parquet', 'daily', '["FR"]', '["legal_units_SIREN","establishments_SIRET","names","addresses","activity_codes","active_and_closed_status","historical_changes","succession_links"]', '["bulk snapshots are multi-gigabyte; use streaming, Parquet or filtered exports rather than Git storage","preserve source date and required Licence Ouverte attribution","apply separate personal-data review to natural-person/sole-proprietor records and suppressions"]', '["https://www.insee.fr/fr/information/3591226","https://www.data.gouv.fr/datasets/base-sirene-des-entreprises-et-de-leurs-etablissements-siren-siret"]', 'candidate', 'pending', NULL, '2026-11-07'),
('estonia-rik-e-business-register', 'Estonia RIK e-Business Register open data', 'Centre of Registers and Information Systems (RIK)', 'https://avaandmed.ariregister.rik.ee/en/downloading-open-data', 'CC-BY-4.0', 'approved', 1, 1, 1, 'Source: Estonian e-Business Register open data, Centre of Registers and Information Systems (RIK), CC BY 4.0.', 'free_daily_machine_readable_XML_JSON_and_selected_CSV', 'daily', '["EE"]', '["legal_person_names","registry_codes","legal_forms","VAT_numbers","status","first_entry_dates","addresses"]', '["accept the current dataset licence terms before download","use only the public open-data datasets and exclude personal identification numbers","do not ingest persons, beneficial owners, shareholders or contact data without field-specific GDPR and source-term review","current bulk files cover registered, liquidation and bankruptcy statuses; they do not represent a complete deleted-history archive"]', '["https://avaandmed.ariregister.rik.ee/en/downloading-open-data","https://avaandmed.ariregister.rik.ee/en/terms-service","https://creativecommons.org/licenses/by/4.0/"]', 'candidate', 'pending', NULL, '2026-11-07'),
('netherlands-kvk-basic-company-hvds', 'Netherlands KVK Business Register Open Dataset — Basic Company Information', 'Kamer van Koophandel (KVK)', 'https://www.kvk.nl/en/ordering-products/kvk-business-register-open-data-set/', 'CC-BY-4.0', 'approved', 1, 1, 1, 'Source: KVK Business Register Open Dataset Basic Company Information, CC BY 4.0.', 'free_bulk_CSV_and_API', 'every_working_day', '["NL"]', '["start_date","active_status","insolvency_status","legal_structure","postcode_region_first_two_digits","SBI_activities","main_activities","member_state"]', '["this high-value dataset intentionally excludes company name and KVK number, so it is not suitable for entity-level directory lookup","it excludes sole proprietorships and full postcode","do not enrich or combine the dataset in a way that makes records traceable to an individual person","use for aggregated market intelligence and benchmarking only"]', '["https://www.kvk.nl/en/ordering-products/kvk-business-register-open-data-set/","https://developers.kvk.nl/documentation/open-dataset-basis-bedrijfsgegevens-api","https://data.overheid.nl/en/dataset/f085379e-f007-4b90-aa5d-06c159d2845a"]', 'candidate', 'not_required', NULL, '2026-11-07'),
('slovenia-ajpes-prs', 'Slovenian Business Register (PRS)', 'Agency of the Republic of Slovenia for Public Legal Records and Related Services (AJPES)', 'https://podatki.gov.si/dataset/poslovni-register-slovenije', 'CC-BY-4.0', 'approved', 1, 1, 1, 'Source: Poslovni register Slovenije (PRS), AJPES, CC BY 4.0.', 'open_bulk_CSV', 'every_two_weeks', '["SI"]', '["business_subjects","branches","foreign_business_branches","registration_numbers","legal_names","registered_addresses","legal_forms","business_status"]', '["the register also contains sole proprietors and natural persons carrying out registered activity; filter these before public company-directory display","preserve source date and attribution","do not imply AJPES endorsement or official status for ExportFlow"]', '["https://podatki.gov.si/dataset/poslovni-register-slovenije","https://www.ajpes.si/Registers/Slovenian_Business_Register"]', 'candidate', 'pending', NULL, '2026-11-07'),
('lithuania-centre-of-registers-open-financial-data', 'Lithuania Centre of Registers open company data and financial reports', 'State Enterprise Centre of Registers (Registrų centras)', 'https://polonepp.registrucentras.lt/en/reports-and-statistics/open-data', 'CC-BY-4.0', 'approved', 1, 1, 1, 'Source: State Enterprise Centre of Registers (Registrų centras), Lithuania open data, CC BY 4.0.', 'published_open_datasets; detailed_registry_records_require_registered_service_agreement', 'dataset_specific', '["LT"]', '["selected_open_register_data","published_company_financial_reports_where_designated_open"]', '["CC BY 4.0 applies to the Centre''s published open-data datasets, not automatically to every legal-entity register record or document","detailed company register data are restricted to registered users with a service agreement and a 100-search/day public-search limit","do not scrape the restricted public-search interface or ingest paid document copies as if they were open data","capture each dataset''s exact scope and schema before importing"]', '["https://polonepp.registrucentras.lt/en/reports-and-statistics/open-data","https://www.registrucentras.lt/jar/p_en/"]', 'candidate', 'not_required', NULL, '2026-11-07');
